pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, uint256 stray) public {
        amount = bound(amount, 1, 1 ether);

        Reverter r = new Reverter();

        vm.deal(address(c), 1 ether);

        bytes memory data = abi.encodePacked(stray);

        GasHungry gh = new GasHungry();

        bool ok;
        try c.sendMoney(address(gh), amount, data) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract GasHungry {
    uint public hits;
    fallback() external payable {
        for (uint i = 0; i < 1000; i++) {
            hits += i;
        }
    }
}

contract Reverter { fallback() external payable { revert(); } }
